<div class="heading"><div><span class="eyebrow">QUICKSALE</span><h1><?= esc($heading) ?></h1></div><a class="button" href="<?= esc($backUrl) ?>">Back</a></div><section class="panel form-grid"><form method="post" action="<?= esc($action) ?>" enctype="multipart/form-data"><?= csrf_field() ?><?php foreach(session()->getFlashdata('errors')??[] as $e): ?><div class="flash error"><?= esc($e) ?></div><?php endforeach ?><?php foreach($fields as $f): $v=old($f['name'],$record[$f['name']]??''); ?><label><?= esc($f['label']) ?><?php if(($f['type']??'')==='file'): ?><input type="file" name="<?= esc($f['name']) ?>" accept="image/jpeg,image/png,image/gif,image/webp"><?php else: ?><input name="<?= esc($f['name']) ?>" type="<?= esc($f['type']??'text') ?>" value="<?= ($f['type']??'')==='password'?'':esc($v) ?>" <?= isset($f['step'])?'step="'.esc($f['step']).'"':'' ?> <?= !empty($f['required'])?'required':'' ?>><?php endif ?></label><?php endforeach ?><button class="button primary">Save</button></form></section>